def handle_moban_file(moban_file, options):
    """
    act upon default moban file
    """
    if not os.path.exists(moban_file):
        raise Exception("moban file not found: %s" % moban_file)
    if not os.path.exists(options.output_dir):
        os.makedirs(options.output_dir)
    if not os.path.exists(options.output_dir):
        raise Exception("output dir not found: %s" % options.output_dir)
    with open(moban_file, "r") as f:
        data = yaml.load(f)
    if "moban" not in data:
        raise Exception("moban file is not valid")
    if "version" not in data["moban"]:
        raise Exception("moban file is not valid")
    if data["moban"]["version"] != "1.0":
        raise Exception("moban file is not valid")
    if "templates" not in data["moban"]:
        raise Exception("moban file is not valid")
    if "output_dir" not in data["moban"]:
        raise Exception("moban file is not valid")
    if "output_dir" in data["moban"]:
        options.output_dir = data["moban"]["output_dir"]
    if "template_dirs" not in data["moban"]:
        raise Exception("moban file is not valid")
    if "template_dirs" in data["moban"]:
        options.template_dirs = data["moban"]["template_dirs"]
    if "template_file_suffix" not in data["moban"]:
        raise Exception("moban file is not valid")
    if "template_file_suffix" in data["moban"]:
        options.template_file_suffix = data["moban"]["template_file_suffix"]
    if "encoding" not in data["moban"]:
        raise Exception("moban file is not valid")
    if "encoding" in data["moban"]:
        options.encoding = data["moban"]

